-- Complete the two owner-only Box BBQ drafts without publishing them or changing prices
BEGIN;
SET LOCAL lock_timeout='5s';
CREATE TEMP TABLE box_draft_before ON COMMIT DROP AS SELECT md5(coalesce(jsonb_agg(CASE WHEN id IN ('f5125442-d30f-4032-8605-0cfdd6ed553d','e3e401d8-679b-4420-81cd-edc7ac1a2804') THEN to_jsonb(p)-'image_storage_path'-'updated_at' ELSE to_jsonb(p) END ORDER BY id)::text,'')) snapshot FROM public.menu_products p;
DO $guard$ BEGIN
IF NOT EXISTS(SELECT 1 FROM public.cafes WHERE id='318df308-e39f-4ef2-a0fd-05c126720d82' AND slug='brand-bd0eeac9e747' AND deleted_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.menu_products WHERE id='f5125442-d30f-4032-8605-0cfdd6ed553d' AND cafe_id='318df308-e39f-4ef2-a0fd-05c126720d82' AND name='تشيكن فرايز' AND NOT available AND price=0 AND deleted_at IS NULL AND (image_storage_path IS NULL OR image_storage_path='318df308-e39f-4ef2-a0fd-05c126720d82/f5125442-d30f-4032-8605-0cfdd6ed553d/four-brands-20261102-draft-295af5e6cf35b697.webp')) THEN RAISE EXCEPTION 'Box draft changed; preserve owner edits and review';END IF;
IF NOT EXISTS(SELECT 1 FROM public.cafes WHERE id='318df308-e39f-4ef2-a0fd-05c126720d82' AND slug='brand-bd0eeac9e747' AND deleted_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.menu_products WHERE id='e3e401d8-679b-4420-81cd-edc7ac1a2804' AND cafe_id='318df308-e39f-4ef2-a0fd-05c126720d82' AND name='صوص الجبن' AND NOT available AND price=0 AND deleted_at IS NULL AND (image_storage_path IS NULL OR image_storage_path='318df308-e39f-4ef2-a0fd-05c126720d82/e3e401d8-679b-4420-81cd-edc7ac1a2804/four-brands-20261102-draft-9774814ee6452b19.webp')) THEN RAISE EXCEPTION 'Box draft changed; preserve owner edits and review';END IF;
END $guard$;
UPDATE public.menu_products SET image_storage_path='318df308-e39f-4ef2-a0fd-05c126720d82/f5125442-d30f-4032-8605-0cfdd6ed553d/four-brands-20261102-draft-295af5e6cf35b697.webp',updated_at=now() WHERE id='f5125442-d30f-4032-8605-0cfdd6ed553d' AND cafe_id='318df308-e39f-4ef2-a0fd-05c126720d82' AND NOT available AND price=0 AND image_storage_path IS NULL;
UPDATE public.menu_products SET image_storage_path='318df308-e39f-4ef2-a0fd-05c126720d82/e3e401d8-679b-4420-81cd-edc7ac1a2804/four-brands-20261102-draft-9774814ee6452b19.webp',updated_at=now() WHERE id='e3e401d8-679b-4420-81cd-edc7ac1a2804' AND cafe_id='318df308-e39f-4ef2-a0fd-05c126720d82' AND NOT available AND price=0 AND image_storage_path IS NULL;
DO $verify$ DECLARE actual text; BEGIN SELECT md5(coalesce(jsonb_agg(CASE WHEN id IN ('f5125442-d30f-4032-8605-0cfdd6ed553d','e3e401d8-679b-4420-81cd-edc7ac1a2804') THEN to_jsonb(p)-'image_storage_path'-'updated_at' ELSE to_jsonb(p) END ORDER BY id)::text,'')) INTO actual FROM public.menu_products p;IF actual IS DISTINCT FROM (SELECT snapshot FROM box_draft_before) THEN RAISE EXCEPTION 'Product fields changed beyond images';END IF;END $verify$;
COMMIT;
